import CryptoKit
import Foundation

/// Replays bytes made by the real Python MOSS (TestVectors.swift, generated by
/// tools/make_ios_vectors.py) to prove this phone speaks MOSS exactly: the same
/// sealed request, the same keys, the capsule and spores opened, the page's
/// hash, pings and pongs. Needs no radio.
struct CheckResult: Identifiable {
    let id = UUID()
    let name: String
    let passed: Bool
    let detail: String
}

enum SelfCheck {
    static func run() -> [CheckResult] {
        var out: [CheckResult] = []
        func check(_ name: String, _ body: () throws -> String?) {
            do {
                if let problem = try body() {
                    out.append(CheckResult(name: name, passed: false, detail: problem))
                } else {
                    out.append(CheckResult(name: name, passed: true, detail: ""))
                }
            } catch {
                out.append(CheckResult(name: name, passed: false, detail: "\(error)"))
            }
        }
        let v = TestVectors.self

        check("#moss channel key") {
            MC.hashtagSecret("#moss") == v.mossSecret ? nil : "got \(MC.hashtagSecret("#moss").hex)"
        }
        check("Seed Vault hello (Ed25519 signature)") {
            guard let h = Seal.verifyHello(v.hello) else { return "signature didn't verify" }
            if h.x != v.vaultXPub || h.ed != v.vaultEdPub { return "wrong keys" }
            if h.name != v.vaultName { return "name \(h.name)" }
            if h.version != v.helloVersion || h.protocolLevel != v.helloProtocol { return "version \(h.version ?? "-")" }
            return nil
        }
        check("A forged hello is refused") {
            var bad = v.hello
            bad[40] ^= 0x01
            return Seal.verifyHello(bad) == nil ? nil : "accepted a tampered hello"
        }
        check("Fingerprint") {
            let fp = Seal.fingerprint(x: v.vaultXPub, ed: v.vaultEdPub)
            return fp == v.fingerprint ? nil : "got \(fp)"
        }

        var session: ReaderSession? = nil
        check("Sealed request (X25519 + HKDF + ChaCha20-Poly1305)") {
            let eph = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: v.readerEphPrivate)
            let s = try ReaderSession(vaultX: v.vaultXPub, rid: v.rid, kind: Moss.kindArticle, query: v.title,
                                      ephemeral: eph, paddingByte: v.paddingByte)
            session = s
            if s.request.count != Moss.maxDatagram { return "\(s.request.count) bytes, not 163" }
            return s.request == v.request ? nil : "bytes differ from Python's"
        }
        var capsule: ReaderSession.Capsule? = nil
        check("Capsule opens") {
            guard let s = session else { return "no session" }
            let c = try s.openCapsule(v.capsule)
            capsule = c
            return c.total == v.chunks.count ? nil : "says \(c.total) spores, expected \(v.chunks.count)"
        }
        check("Spores open into the page, and its hash matches") {
            guard let s = session, let c = capsule else { return "no capsule" }
            var wire = Data()
            for raw in v.chunks {
                guard let piece = Moss.parseChunk(raw) else { return "bad spore" }
                wire.append(piece.payload)
            }
            let body = try s.openBody(wire, bodyLength: c.bodyLength)
            if body.name != v.title { return "name \(body.name)" }
            guard let page = Moss.inflate(body.blob) else { return "zlib failed" }
            if page.count != v.articleLength { return "\(page.count) bytes" }
            if Data(SHA256.hash(data: page)) != v.articleSHA256 { return "SHA-256 differs" }
            if Data(SHA256.hash(data: page)).slice(0, 8) != c.hash { return "capsule hash differs" }
            let text = String(decoding: page, as: UTF8.self)
            return text.hasPrefix(v.articleStart) ? nil : "text starts wrong"
        }
        check("A damaged spore is caught") {
            guard let s = session, let c = capsule else { return "no capsule" }
            var wire = Data()
            for raw in v.chunks {
                if let piece = Moss.parseChunk(raw) { wire.append(piece.payload) }
            }
            wire[5] ^= 0x80
            do {
                _ = try s.openBody(wire, bodyLength: c.bodyLength)
                return "accepted a damaged page"
            } catch {
                return nil
            }
        }
        check("Sealed error opens") {
            let eph = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: v.readerEphPrivate)
            let fresh = try ReaderSession(vaultX: v.vaultXPub, rid: v.rid, kind: Moss.kindArticle, query: v.title,
                                          ephemeral: eph, paddingByte: v.paddingByte)
            let text = try fresh.openError(v.error)
            return text == v.errorText ? nil : "got \(text)"
        }
        check("Repair request, done, whois") {
            if Moss.makeNack(v.rid, missing: [3, 7, 300]) != v.nack { return "repair request differs" }
            if Moss.makeDone(v.rid) != v.done { return "done differs" }
            if Moss.makeWhois(v.rid) != v.whois { return "whois differs" }
            guard let st = Moss.parseStatus(v.status), st.state == Moss.stateQueued, st.value == 2 else { return "status" }
            return nil
        }
        check("Ping and pong") {
            if Moss.makePing(runID: 0xBEEF, seq: 12, zeroHop: true) != v.ping { return "ping differs" }
            guard let p = Moss.parsePong(v.pong) else { return "pong didn't parse" }
            if p.runID != 0xBEEF || p.seq != 12 || p.snr != -6.75 || p.rssi != -97 || p.hops != 255 || p.name != v.vaultName {
                return "pong fields wrong"
            }
            return nil
        }
        return out
    }
}
